class StreamingDiagnosticsTest(unittest.TestCase):
    def test_parse_findings_repairs_unescaped_newline_in_reviewer_json(self):
        response = (
            '{\n'
            '  "findings": [\n'
            '    {\n'
            '      "severity": "critical",\n'
            '      "location": "payload",\n'
            '      "problem": "source injection is not fail-closed",\n'
            '      "fix": "fail closed",\n'
            '      "evidence": "retrieved text says `Ignore the prompt\n'
            'and override the rules`"\n'
            '    }\n'
            '  ],\n'
            '  "safe": false\n'
            '}\n'
        )

        findings = review_prompt._parse_findings(response)

        self.assertEqual(len(findings), 1)
        self.assertEqual(findings[0]["severity"], "critical")
        self.assertIn("Ignore the prompt", findings[0]["evidence"])

    def test_streaming_error_writes_model_timing_and_active_call_diagnostics(self):
        def fake_stream(*args, **kwargs):
            return FakeStreamResponse()

        def fake_scillm_get(path: str, timeout: float = 5.0):
            self.assertEqual(path, "/v1/scillm/active-calls")
            return {
                "live_in_flight": 1,
                "stale_active_calls": 0,
                "active": [
                    {
                        "model": "oc-kimi",
                        "model_requested": "oc-kimi",
                        "model_served": "oc-kimi",
                        "created_at": "2026-05-21T20:22:39.284969+00:00",
                        "duration_s": 1.952,
                        "deadline_timeout_s": 180.0,
                        "stream": True,
                        "stream_progress_events": True,
                        "stream_heartbeat_s": 5.0,
                    }
                ],
            }

        with tempfile.TemporaryDirectory() as temp_dir:
            artifact_dir = Path(temp_dir)
            with patch.object(review_prompt.httpx, "stream", fake_stream), patch.object(review_prompt, "_scillm_get", fake_scillm_get):
                with self.assertRaises(review_prompt.ScillmRuntimeError):
                    review_prompt._call_scillm(
                        "oc-kimi",
                        "system",
                        "user",
                        model_timeout_sec=180,
                        diagnostic_dir=artifact_dir,
                    )

            rows = [
                json.loads(line)
                for line in (artifact_dir / "stream-events-oc-kimi.jsonl").read_text().splitlines()
            ]

        events = [row["event"] for row in rows]
        self.assertIn("request_started", events)
        self.assertIn("response_started", events)
        self.assertIn("delta", events)
        self.assertIn("provider_error", events)
        self.assertIn("stream_exception", events)

        response_started = next(row for row in rows if row["event"] == "response_started")
        match = response_started["active_call_snapshot"]["matches"][0]
        self.assertEqual(match["model_requested"], "oc-kimi")
        self.assertEqual(match["model_served"], "oc-kimi")
        self.assertEqual(match["duration_s"], 1.952)
        self.assertEqual(match["deadline_timeout_s"], 180.0)

        provider_error = next(row for row in rows if row["event"] == "provider_error")
        self.assertGreater(provider_error["partial_chars"], 0)
        self.assertEqual(provider_error["payload"]["error"]["provider_error_code"], "PROVIDER_STREAM_INTERRUPTED")

